INSERT INTO "StorePolicy" ("id", "slug", "titleAr", "titleEn", "contentAr", "contentEn", "isActive", "updatedAt") VALUES
  ('policy_privacy_default', 'privacy', 'سياسة الخصوصية', 'Privacy Policy', 'نحترم خصوصيتك ونستخدم بيانات الطلب والتواصل فقط لمعالجة طلباتك، تقديم الدعم، والالتزام بالمتطلبات القانونية. لا نبيع بياناتك الشخصية. يمكنك التواصل معنا لطلب تحديث بياناتك أو الاستفسار عنها.', 'We respect your privacy and use order and contact information only to process orders, provide support, and meet legal obligations. We do not sell personal data. Contact us to update your information or ask about it.', true, CURRENT_TIMESTAMP),
  ('policy_refunds_default', 'refunds', 'سياسة الاسترجاع والاسترداد', 'Return & Refund Policy', 'يرجى التواصل معنا قبل إعادة أي منتج. تخضع طلبات الاسترجاع أو الاسترداد لحالة المنتج وطبيعة الطلب وأي شروط قانونية واجبة التطبيق. سنوضح لك خطوات المعالجة بعد مراجعة الطلب.', 'Please contact us before returning any product. Return and refund requests depend on the product condition, the nature of the order, and applicable legal requirements. We will explain the next steps after reviewing your request.', true, CURRENT_TIMESTAMP),
  ('policy_shipping_default', 'shipping', 'سياسة الشحن', 'Shipping Policy', 'تظهر خيارات وتكاليف الشحن المتاحة عند إتمام الطلب. قد تختلف مدة التسليم بحسب المنطقة وتوفر المنتجات. سنتواصل معك عند الحاجة لتأكيد تفاصيل التسليم.', 'Available shipping options and costs are shown at checkout. Delivery times may vary by area and product availability. We will contact you when delivery details need confirmation.', true, CURRENT_TIMESTAMP)
